9	  /** Number of samples across every window. */
10	  count: number;
11	  mean: number;
12	  min: number;
13	  max: number;
14	  /** Bounds of the covered span, or null when there is nothing to cover. */
15	  from: number | null;
16	  to: number | null;
17	}
18	
19	export function summarize(windows: Window[], series: string): Summary {
20	  if (windows.length === 0) {
21	    return { series, count: 0, mean: 0, min: 0, max: 0, from: null, to: null };
22	  }
23	
24	  let count = 0;
25	  let sum = 0;
26	  let min = Infinity;
27	  let max = -Infinity;
28	
29	  for (const window of windows) {
30	    count += window.count;
31	    sum += window.sum;
32	    min = Math.min(min, window.min);
33	    max = Math.max(max, window.max);
34	  }
35	
36	  return {
37	    series,
38	    count,
39	    mean: count === 0 ? 0 : sum / count,
40	    min,
41	    max,
42	    from: windows[0].from,
43	    to: windows[windows.length - 1].to,
44	  };
45	}
46	
47	export function formatSummary(summary: Summary): string {
48	  if (summary.count === 0) {
49	    return `${summary.series}: no samples`;
50	  }
51	  const mean = summary.mean.toFixed(2);
52	  return `${summary.series}: n=${summary.count} mean=${mean} min=${summary.min} max=${summary.max}`;
53	}
